async function puGuardarRes(a,r){r=r||await puRpc('pulso_resultados',{p_ativ:a.id});const P=r.ativ.perguntas||[];const ch=r.chave||{certas:[],exp:[]};
  a.res={em:Date.now(),estado:r.ativ.estado,al:r.alunos.map(x=>({id:x.id,n:x.nome,ref:x.ref,eq:x.equipa,pts:+x.pontos,c:x.certas,al:(a.liga||{})[x.id]||''})),resp:r.resp.map(x=>[x.a,x.p,x.opc,x.texto,x.certa==null?null:x.certa?1:0,+x.pts,x.votos]),
    perg:P.map((p,i)=>({t:p.t,tp:p.tp,o:p.o,pts:p.pts,c:(ch.certas[i]||{}).c||[],a:(ch.certas[i]||{}).a||[],exp:(ch.exp||[])[i]||''}))};
  if(a.lista){S.cfg.pulsoSal=S.cfg.pulsoSal||'';const t=puTurmas().find(z=>z.id===a.turma);if(t)for(const x of a.res.al){if(x.ref&&!x.al){for(const y of alunosAval(t)){if((await PU.sha('es-pulso-ref:'+S.cfg.pulsoSal+':'+(y.cid||y.id))).slice(0,32)===x.ref){x.al=y.id;break}}}}}
  a.fim=r.ativ.estado==='fim';save();return a.res}
async function puRelLista(){const el=$('#pu-rels');const d=puD();let viv=new Map();try{const m=await puRpc('pulso_minhas',{});viv=new Map((m.ativs||[]).map(x=>[x.id,x]))}catch(_){}if(!$('#pu-rels'))return;
  el.innerHTML=d.ativ.length?`<div class="arjl">${d.ativ.map(a=>{const v=viv.get(a.id);const s=d.salas.find(z=>z.id===a.sala);return `<article class="arji"><span class="arjic" style="--mc:${PU_ATIV[a.tipo][2]}">${PU_ATIV[a.tipo][1]}</span><div class="arjb"><b>${esc(a.nome)}</b><span class="mut">${PU_ATIV[a.tipo][0]} · ${s?esc(s.nome):'sala apagada'} · ${new Date(a.criado).toLocaleString('pt-PT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}${v?' · '+v.alunos+' alunos':a.res?' · '+a.res.al.length+' alunos':''}</span></div><span class="tag ${v&&v.estado!=='fim'?'ok':''}">${v?v.estado==='fim'?'Terminada':'A decorrer':a.res?'Guardado':'Expirado'}</span>
      <div class="arja">${v&&v.estado!=='fim'?`<button class="btn sm pri" data-prv="${a.id}">${ic('chart',13)} Ao Vivo</button>`:''}${v||a.res?`<button class="btn sm" data-prr="${a.id}">${ic('file',13)} Relatório</button>`:''}<button class="btn sm ico dng" data-prx="${a.id}" aria-label="Apagar">${ic('trash',13)}</button></div></article>`}).join('')}</div>`:`<div class="empty">${ic('chart',26)}<br><b>Ainda sem atividades</b></div>`;
  $$('#pu-rels [data-prv]').forEach(b=>b.onclick=()=>{UI.puVivo=b.dataset.prv;vPulso()});
  $$('#pu-rels [data-prr]').forEach(b=>b.onclick=async()=>{const a=d.ativ.find(x=>x.id===b.dataset.prr);if(viv.has(a.id))try{await puGuardarRes(a)}catch(e){toast(e.message,'erro')}if(a.res){UI.puRel=a.id;vPulso()}});
  $$('#pu-rels [data-prx]').forEach(b=>b.onclick=async()=>{const a=d.ativ.find(x=>x.id===b.dataset.prx);if(!confirm('Apagar «'+a.nome+'» e o relatório?'))return;if(viv.has(a.id))try{await puRpc('pulso_controlo',{p_ativ:a.id,p_acao:'apagar',p_arg:{}})}catch(_){}d.ativ=d.ativ.filter(x=>x!==a);save();puRelLista()})}
function puAnalise(a){const R=a.res;const P=R.perg;const mx=P.reduce((s,p)=>s+(+p.pts||1),0)||1;
  const porA=R.al.map(x=>{const L=R.resp.filter(z=>z[0]===x.id);const pts=L.reduce((s,z)=>s+(+z[5]||0),0);return {...x,nr:L.length,ok:L.filter(z=>z[4]===1).length,pts,pct:a.tipo==='saida'||a.tipo==='rapida'?null:pts/mx}});
  const porP=P.map((p,i)=>{const L=R.resp.filter(z=>z[1]===i);const cor=L.filter(z=>z[4]!=null);return {p,i,n:L.length,ok:cor.filter(z=>z[4]===1).length,taxa:cor.length?cor.filter(z=>z[4]===1).length/cor.length:null,dist:(p.o||[]).map((_,k)=>L.filter(z=>(z[2]||[]).includes(k)).length),txt:L.filter(z=>z[3]).map(z=>({t:z[3],c:z[4],v:z[6],a:(R.al.find(q=>q.id===z[0])||{}).n}))}});return {porA,porP,mx}}
function puRespTxt(p,z){if(!z)return '—';if(p.tp==='rc'||p.tp==='txt')return z[3]||'';if(p.tp==='escala')return PU_ESCALA[(z[2]||[])[0]]||'';return (z[2]||[]).map(k=>p.tp==='vf'?p.o[k]:PU_LETRA[k]+') '+(p.o[k]||'')).join('; ')}
function puCertaTxt(p){if(p.tp==='rc')return (p.a||[]).join(' / ')||'(correção manual)';if(p.tp==='txt'||p.tp==='escala')return '';return (p.c||[]).map(k=>p.tp==='vf'?p.o[k]:PU_LETRA[k]+') '+(p.o[k]||'')).join('; ')}
function puRelatorio(a){const R=a.res;const {porA,porP}=puAnalise(a);const P=R.perg;const s=puD().salas.find(z=>z.id===a.sala);const corP=v=>v==null?'#94a3b8':v<.5?'#dc2626':v<.7?'#d97706':'#16a34a';
  const med=porA.filter(x=>x.pct!=null);const media=med.length?med.reduce((q,x)=>q+x.pct,0)/med.length:null;const TT=puTurmas();const tSel=TT.find(z=>z.id===(a.assoc&&a.assoc.turma||a.turma||UI.puRelT))||T()||TT[0];const AL=tSel?alunosAval(tSel):[];
  barBtns([{id:'pr-v',t:ic('back',15)+' Relatórios',f:()=>{UI.puRel=null;UI.puTab='rel';vPulso()}},{id:'pr-x',t:ic('download',15)+' Excel da Turma',f:()=>puExcel(a)},{id:'pr-pa',t:ic('file',15)+' PDF por Aluno',f:()=>puPdfAlunos(a)},{id:'pr-pq',t:ic('file',15)+' PDF por Pergunta',f:()=>puPdfPerguntas(a)}]);
  $('#view').innerHTML=`<div class="arv arrel"><div class="card"><div class="row" style="gap:12px;flex-wrap:wrap"><span class="arjic" style="--mc:${PU_ATIV[a.tipo][2]}">${PU_ATIV[a.tipo][1]}</span><div style="flex:1"><h2 style="margin:0">${esc(a.nome)}</h2><span class="mut">${PU_ATIV[a.tipo][0]}${a.tipo==='quiz'?' · '+PU_MODOS[a.modo][0]:''} · ${s?esc(s.nome):''} · ${new Date(a.criado).toLocaleString('pt-PT')}</span></div></div>
    <div class="kpis" style="margin-top:12px"><div class="kpi"><div class="l">${ic('users',14)} Alunos</div><div class="v">${R.al.length}</div></div>${media!=null?`<div class="kpi"><div class="l">${ic('check',14)} Média</div><div class="v" style="color:${corP(media)}">${Math.round(media*100)}%</div></div>`:''}<div class="kpi"><div class="l">${ic('clipboard',14)} Perguntas</div><div class="v">${P.length}</div></div><div class="kpi"><div class="l">${ic('list',14)} Respostas</div><div class="v">${R.resp.length}</div></div></div></div>
    ${a.tipo!=='saida'&&a.tipo!=='rapida'?`<div class="card"><h2>${ic('users',18)} Por aluno</h2><div class="tblw"><table class="lst"><thead><tr><th>Aluno</th>${!a.lista?'<th>Na turma</th>':''}<th>Certas</th><th>Pontos</th><th>Nota</th>${P.map((_,i)=>`<th>${i+1}</th>`).join('')}</tr></thead><tbody>${porA.map(x=>`<tr><td><b>${esc(x.n)}</b></td>${!a.lista?`<td><select data-prlg="${x.id}" aria-label="Aluno"><option value="">—</option>${AL.map(y=>`<option value="${y.id}" ${x.al===y.id?'selected':''}>${esc(numAl(y))}. ${esc(y.nome)}</option>`).join('')}</select></td>`:''}<td>${x.ok}/${P.length}</td><td>${Math.round(x.pts*10)/10}</td><td><b style="color:${corP(x.pct)}">${x.pct==null?'—':Math.round(x.pct*100)+'%'}</b></td>${P.map((p,i)=>{const z=R.resp.find(q=>q[0]===x.id&&q[1]===i);return `<td class="${!z?'pucv':z[4]===1?'pucc':z[4]===0?'puce':'pucp'}" title="${esc(puRespTxt(p,z))}">${!z?'·':z[4]===1?'✓':z[4]===0?'✗':'?'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>
      <div class="row" style="gap:8px;margin-top:12px;flex-wrap:wrap"><span class="mut">${a.assoc?'Na turma: '+esc(a.assoc.txt):'Os resultados entram na turma como instrumento <b>formativo</b> (não conta para a nota), a não ser que escolha um domínio.'}</span><span class="sp1"></span>
        <select id="pr-t" style="width:auto">${TT.map(z=>`<option value="${z.id}" ${tSel&&tSel.id===z.id?'selected':''}>${esc(z.nome)} · ${esc(z.disciplina)}</option>`).join('')}</select><select id="pr-dom" style="width:auto"><option value="">Formativo (não conta)</option>${(tSel?tSel.dominios:[]).map(dm=>`<option value="${dm.id}" ${a.assoc&&a.assoc.dom===dm.id?'selected':''}>Conta em: ${esc(dm.nome)}</option>`).join('')}</select><button class="btn pri" id="pr-as">${ic('plus',15)} ${a.assoc?'Atualizar na Turma':'Associar à Turma'}</button></div></div>`:''}
    <div class="card"><h2>${ic('clipboard',18)} Por pergunta</h2>${porP.map(x=>`<div class="arrq"><div class="row" style="gap:8px"><b>${x.i+1}.</b><span style="flex:1">${esc(x.p.t||'(pergunta oral)')}</span>${x.taxa!=null?`<b style="color:${corP(x.taxa)}">${Math.round(x.taxa*100)}%</b>`:''}</div>
      ${x.p.tp==='rc'||x.p.tp==='txt'?`<div class="purc">${x.txt.map(z=>`<div class="purci ${z.c===1?'ok':z.c===0?'no':''}"><span>${esc(z.t)}</span><small class="mut">${esc(z.a||'')}</small>${z.v?`<b class="puvt">${z.v} votos</b>`:''}</div>`).join('')||'<span class="mut">Sem respostas.</span>'}</div>`:`<div class="arrqo">${(x.p.o||[]).map((o,k)=>`<span class="${(x.p.c||[]).includes(k)?'ok':''}"><i style="--oc:#127fa6">${(x.p.c||[]).includes(k)?'✓':x.p.tp==='escala'?'•':PU_LETRA[k]}</i>${esc(o)} <b>${x.dist[k]||0}</b></span>`).join('')}</div>`}${x.p.exp?`<p class="hint" style="margin:4px 0 0">${esc(x.p.exp)}</p>`:''}</div>`).join('')}</div></div>`;
  $$('#view [data-prlg]').forEach(sl=>sl.onchange=()=>{a.liga=a.liga||{};a.liga[sl.dataset.prlg]=sl.value;const x=R.al.find(z=>z.id===sl.dataset.prlg);if(x)x.al=sl.value;save()});
  const pt=$('#pr-t');if(pt)pt.onchange=()=>{UI.puRelT=pt.value;a.turma=a.turma||'';puRelatorio(a)};
  const as=$('#pr-as');if(as)as.onclick=()=>puAssociar(a,porA,TT.find(z=>z.id===$('#pr-t').value),$('#pr-dom').value)}
function puAssociar(a,porA,t,dom){if(!t)return toast('Escolha a turma','aviso');const R=a.res;const lig=porA.map(x=>({...x,al:(R.al.find(z=>z.id===x.id)||{}).al})).filter(x=>x.al&&x.pct!=null&&t.alunos.some(y=>y.id===x.al));if(!lig.length)return toast(a.lista?'Nenhum aluno da lista respondeu.':'Ligue pelo menos um aluno da turma.','aviso');
  if(dom&&!confirm('Este resultado vai CONTAR para a classificação no domínio escolhido. Confirma?'))return;
  let i=a.assoc&&t.instrumentos.find(z=>z.id===a.assoc.inst);if(!i){i={id:uid(),nome:'Pulso · '+a.nome,tipo:dom?'Pulso (avaliação)':'Pulso (formativo)',periodo:perAtual(t),data:new Date(a.criado).toISOString().slice(0,10),itens:[{id:uid(),rot:'Resultado (%)',dom:dom||'',cot:100}],notas:{},pulso:a.id};t.instrumentos.push(i)}
  i.itens[0].dom=dom||'';i.tipo=dom?'Pulso (avaliação)':'Pulso (formativo)';const it=i.itens[0].id;lig.forEach(x=>{i.notas[x.al]={[it]:Math.round(x.pct*100)}});
  a.assoc={inst:i.id,turma:t.id,dom:dom||'',txt:t.nome+' · '+lig.length+' alunos · '+(dom?'conta para a nota':'formativo')};save();audit('Pulso','Resultados associados à turma',a.nome+' · '+t.nome+(dom?' (conta)':' (formativo)'));toast('Guardado em '+t.nome+(dom?' (conta para a nota)':' como formativo'),'ok');puRelatorio(a)}
/* Excel (.xlsx) da turma: folha «Alunos» e folha «Perguntas» */
function puXlsx(folhas){const x=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');const col=n=>{let s='';n++;while(n){const m=(n-1)%26;s=String.fromCharCode(65+m)+s;n=Math.floor((n-1)/26)}return s};
  const sh=rows=>`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${rows.map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>typeof v==='number'&&isFinite(v)?`<c r="${col(j)}${i+1}"><v>${v}</v></c>`:`<c r="${col(j)}${i+1}" t="inlineStr"${i===0?' s="1"':''}><is><t xml:space="preserve">${x(v)}</t></is></c>`).join('')}</row>`).join('')}</sheetData></worksheet>`;
  const F=[{nome:'[Content_Types].xml',dados:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${folhas.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`},
    {nome:'_rels/.rels',dados:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`},
    {nome:'xl/workbook.xml',dados:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${folhas.map((f,i)=>`<sheet name="${x(f.nome.slice(0,31))}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`},
    {nome:'xl/_rels/workbook.xml.rels',dados:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${folhas.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId${folhas.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`},
    {nome:'xl/styles.xml',dados:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="2"><xf/><xf fontId="1" applyFont="1"/></cellXfs></styleSheet>`},
    ...folhas.map((f,i)=>({nome:`xl/worksheets/sheet${i+1}.xml`,dados:sh(f.rows)}))];
  return zipCriar(F)}
function puExcel(a){const R=a.res;const {porA,porP}=puAnalise(a);const P=R.perg;
  const A1=[['Aluno','Certas','Pontos','Nota (%)',...P.map((_,i)=>'P'+(i+1))],...porA.map(x=>[x.n,x.ok,Math.round(x.pts*10)/10,x.pct==null?'':Math.round(x.pct*100),...P.map((p,i)=>puRespTxt(p,R.resp.find(z=>z[0]===x.id&&z[1]===i)))])];
  const A2=[['N.º','Pergunta','Tipo','Resposta certa','Respostas','Acerto (%)','Explicação'],...porP.map(x=>[x.i+1,x.p.t,PU_TIPOS[x.p.tp]||x.p.tp,puCertaTxt(x.p),x.n,x.taxa==null?'':Math.round(x.taxa*100),x.p.exp||''])];
  const b=puXlsx([{nome:'Alunos',rows:A1},{nome:'Perguntas',rows:A2}]);const l=document.createElement('a');l.href=URL.createObjectURL(b);l.download=('Pulso - '+a.nome).replace(/[\/\\:*?"<>|]/g,'-')+'.xlsx';document.body.appendChild(l);l.click();l.remove();audit('Pulso','Exportação Excel',a.nome)}
function puImprimir(titulo,html){const w=window.open('','_blank');if(!w)return toast('Permita janelas pop-up para gerar o PDF','aviso');const e=EC()||{};
  w.document.write(`<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><title>${esc(titulo)}</title><style>body{font:12px/1.4 system-ui,sans-serif;color:#1d2731;margin:14mm}h1{font-size:17px;margin:0}h2{font-size:14px;margin:14px 0 4px}.sub{color:#5b6875;margin:2px 0 10px}.pg{page-break-after:always}.pg:last-child{page-break-after:auto}table{border-collapse:collapse;width:100%}td,th{border:1px solid #cfd8e1;padding:4px 6px;text-align:left;vertical-align:top}th{background:#eef3f7}.ok{color:#15803d;font-weight:700}.no{color:#b91c1c;font-weight:700}.m{color:#64748b}.bar{display:inline-block;height:10px;background:#127fa6;border-radius:3px}</style></head><body>${html}</body></html>`);w.document.close();setTimeout(()=>{try{w.focus();w.print()}catch(_){}},350);void e}
function puPdfAlunos(a){const R=a.res;const {porA}=puAnalise(a);const P=R.perg;const s=puD().salas.find(z=>z.id===a.sala);const esc_=EC()||{};
  puImprimir('Relatórios por aluno · '+a.nome,porA.map(x=>`<div class="pg"><h1>${esc(a.nome)}</h1><div class="sub">${esc(esc_.escola||'')} · ${s?esc(s.nome):''} · ${new Date(a.criado).toLocaleDateString('pt-PT')}</div><h2>${esc(x.n)}${x.pct!=null?' — '+Math.round(x.pct*100)+'%':''}</h2>
    <table><thead><tr><th>#</th><th>Pergunta</th><th>A tua resposta</th>${a.tipo!=='saida'?'<th>Resposta certa</th><th></th>':''}</tr></thead><tbody>${P.map((p,i)=>{const z=R.resp.find(q=>q[0]===x.id&&q[1]===i);return `<tr><td>${i+1}</td><td>${esc(p.t)}${p.exp?`<div class="m">${esc(p.exp)}</div>`:''}</td><td>${esc(puRespTxt(p,z))}</td>${a.tipo!=='saida'?`<td>${esc(puCertaTxt(p))}</td><td class="${z&&z[4]===1?'ok':z&&z[4]===0?'no':''}">${!z?'':z[4]===1?'✓':z[4]===0?'✗':'?'}</td>`:''}</tr>`}).join('')}</tbody></table></div>`).join('')||'<p>Sem alunos.</p>')}
function puPdfPerguntas(a){const {porP}=puAnalise(a);puImprimir('Análise por pergunta · '+a.nome,`<h1>${esc(a.nome)} — análise por pergunta</h1><div class="sub">${new Date(a.criado).toLocaleDateString('pt-PT')} · ${a.res.al.length} alunos</div>`+porP.map(x=>`<h2>${x.i+1}. ${esc(x.p.t||'(pergunta oral)')}${x.taxa!=null?' — '+Math.round(x.taxa*100)+'% de acerto':''}</h2>${x.p.tp==='rc'||x.p.tp==='txt'?`<table><tbody>${x.txt.map(z=>`<tr><td class="${z.c===1?'ok':z.c===0?'no':''}">${esc(z.t)}</td><td class="m">${esc(z.a||'')}${z.v?' · '+z.v+' votos':''}</td></tr>`).join('')||'<tr><td class="m">Sem respostas.</td></tr>'}</tbody></table>`:`<table><tbody>${(x.p.o||[]).map((o,k)=>`<tr><td class="${(x.p.c||[]).includes(k)?'ok':''}">${x.p.tp==='vf'||x.p.tp==='escala'?'':PU_LETRA[k]+') '}${esc(o)}</td><td style="width:45%"><span class="bar" style="width:${x.n?100*(x.dist[k]||0)/x.n:0}%"></span> ${x.dist[k]||0}</td></tr>`).join('')}</tbody></table>`}${x.p.exp?`<p class="m">${esc(x.p.exp)}</p>`:''}`).join(''))}

